CREATE TABLE integration_synchronizations(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,connector_id UUID NOT NULL,provider VARCHAR(64) NOT NULL,status VARCHAR(32) NOT NULL,execution_type VARCHAR(32) NOT NULL,execution_time_ms BIGINT NOT NULL DEFAULT 0,records_processed INT NOT NULL DEFAULT 0,records_succeeded INT NOT NULL DEFAULT 0,records_failed INT NOT NULL DEFAULT 0,correlation_id UUID NOT NULL,retry_count INT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL,finished_at TIMESTAMPTZ);
CREATE TABLE integration_schedules(id UUID PRIMARY KEY,tenant_id UUID NOT NULL,connector_id UUID NOT NULL,cron_expression VARCHAR(128) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,last_run_at TIMESTAMPTZ,next_run_at TIMESTAMPTZ);
CREATE INDEX idx_sync_tenant_connector ON integration_synchronizations(tenant_id,connector_id,created_at);CREATE INDEX idx_schedule_due ON integration_schedules(enabled,next_run_at);
